import{_ as i,l as s,o as e,c as n,v as t,p as l,x as r,d,i as p,S as P}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"BGP 直觉","description":"","frontmatter":{"title":"BGP 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bgp-intuition.md","filePath":"cs/bgp-intuition.md","lastUpdated":1789023840000}'),A={name:"cs/bgp-intuition.md"};function B(c,a,h,E,_,u){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="bgp-直觉" tabindex="-1">BGP 直觉 <a class="header-anchor" href="#bgp-直觉" aria-label="Permalink to &quot;BGP 直觉&quot;">​</a></h1><div class="epigraph"><p>BGP 通告的是路径与属性，不是「到目的的最小代价」；谁是客户、谁是对等，比跳数更要紧。</p><footer>—— 据 Rekhter, Li and Hares, RFC 4271, A Border Gateway Protocol 4, 2006 整理</footer></div><p><a href="/cs/ospf-dijkstra">上一课</a>在一个管理域内求最短路。互联网由许多自治系统（AS）组成，运营商不愿意把内部代价暴露给对手，也不愿意为别人的客户免费扛流量。缺口是<strong>路径向量与政策</strong>：BGP 直觉，不是把 Dijkstra 再跑在全球图上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若全球跑 OSPF，图太大，且「最短」与「合同」冲突：客户路由应优先于对等，对等优先于提供者（常见的 Gao–Rexford 直觉）。BGP：通告前缀加上 AS_PATH 等属性；收到后按政策选最佳，再决定是否向邻居通告。AS_PATH 含自己则丢弃，防环。缺口不是 LPM 硬件，而是「选什么、向谁说」。</p><p>本课不把全部属性优先级阶梯背成考试清单。</p><p><span class="marginnote">eBGP 在 AS 之间，iBGP 在 AS 之内分发外部路由。本课只要求：域间是政策，域内仍要有上一课或等价手段把下一跳变成出接口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>会话在 TCP 上（传输课马上出现，这里先承认需要可靠字节——循环依赖用「控制平面需要可靠信道」一笔带过，实现上 BGP 确实跑在 TCP）。通告：NLRI 前缀 + 下一跳 + 路径。撤销：显式或会话断开。选路：本地政策 &gt; AS 路径长度等，再写入 <a href="/cs/lpm">LPM</a>。</p>',9)),(e(),l(P,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NBR%5B%22%E9%82%BB%20AS%20%E9%80%9A%E5%91%8A%22%5D%20--%3E%20POL%5B%22%E8%BF%9B%E5%8F%A3%E6%94%BF%E7%AD%96%22%5D%0A%20%20POL%20--%3E%20BEST%5B%22%E9%80%89%E6%9C%80%E4%BD%B3%E8%B7%AF%E5%BE%84%22%5D%0A%20%20BEST%20--%3E%20FIB%5B%22%E8%A3%85%E8%BF%9B%E8%BD%AC%E5%8F%91%E8%A1%A8%22%5D%0A%20%20BEST%20--%3E%20EXP%5B%22%E5%87%BA%E5%8F%A3%E6%94%BF%E7%AD%96%E5%86%8D%E9%80%9A%E5%91%8A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BGP 让 <a href="/cs/dhcp-nat">NAT</a> 外的公网前缀能在机构间传播，也让默认路由在边缘出现。端到端：政策错误会黑洞或绕远，ICMP 与 TCP 超时是症状。与 DV 的无穷计数不同，AS_PATH 给出路径记忆。与 LS 不同，没有全球一致的边权。</p><p>本课不把泄漏与劫持写成操作手册；安全课谈 RPKI 等。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BGP 共同体的全部运营惯例，不把 SDN 控制器当默认替代。也不把 Anycast DNS 的细节提前。网络层到此能把包送到主机；如何送到<strong>进程</strong>，下一课 UDP 端口。</p><p>MED、本地优先级、AS 路径长度构成选路阶梯的一部分；教学抓住「政策先于跳数」即可，不必背厂商默认次序的每一个并列规则。</p><p>后课默认：跨域按政策路径向量。主机上的进程复用同一 IP，靠传输层端口，下一课 UDP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BGP（RFC 4271）是政策驱动的路径向量，不是全球最短路。</li><li>AS_PATH 防环；客户/对等/提供者决定通告。</li><li>进程到进程的数据报是 UDP 的缺口。</li><li>出处：RFC 4271；Gao and Rexford 政策直觉；Kurose and Ross。</li></ul>',9))])}const f=i(A,[["render",B]]);export{T as __pageData,f as default};
